tool_input.content:
{
  "symbol": {
    "korean": "엘리베이터가 추락하는 꿈",
    "english": "Dream of Elevator Falling",
    "slug": "elevator-falling-dream"
  },
  "summary": {
    "korean": "엘리베이터가 추락하는 꿈은 현실의 불안과 통제력 상실을 반영하는 꿈으로, 꿈속 감정과 상황에 따라 흉몽과 길몽 양면으로 해석될 수 있는 복합적인 꿈입니다.",
    "english": "A dream of an elevator falling reflects real-world anxiety and a sense of losing control, but can be interpreted as either inauspicious or auspicious depending on the emotions and circumstances experienced during the dream."
  },
  "interpretations": [
    {
      "type": "흉몽",
      "korean": "엘리베이터가 빠르게 추락하는 꿈은 대표적인 흉몽으로, 현실에서 뜻밖의 실수나 난관에 부딪힐 것을 경고합니다. 진행 중인 일에 차질이 생기거나, 자신의 지위나 상황이 급격히 악화될 수 있음을 암시해요. 특히 추락 속도가 빠를수록 닥쳐올 어려움에 제대로 대응하기 어렵다는 신호로 해석됩니다. 현재의 사업, 직장, 또는 인간관계에서 예상치 못한 위기가 찾아올 수 있으니 매사에 신중을 기하는 것이 좋습니다.",
      "english": "A rapidly falling elevator is a classic inauspicious dream, warning of unexpected mistakes or serious obstacles in waking life. It suggests that ongoing projects may encounter setbacks, or your status and circumstances could deteriorate sharply. The faster the fall, the more urgent the warning. This dream signals that your business, career, or relationships may face a sudden crisis, urging you to proceed with caution in all matters.",
      "context": "꿈에서 엘리베이터가 빠르게 추락하며 강한 공포감이나 불안감을 느낀 경우, 또는 추락 후 충격을 경험한 경우"
    },
    {
      "type": "길몽",
      "korean": "엘리베이터가 추락하는 꿈이라도 꿈속에서 크게 두렵지 않거나 오히려 편안함을 느꼈다면, 이는 마음먹던 일들이 술술 풀리는 길몽으로 해석할 수 있어요. 오랫동안 짓눌렸던 고민거리나 스트레스가 해소되고 안정을 되찾는 신호이기도 합니다. 또한 엘리베이터가 추락하다가 중간에 멈추거나 살아서 탈출하는 꿈은 위기를 극복하고 새로운 기회를 얻게 됨을 뜻하기도 합니다.",
      "english": "Even when an elevator falls in a dream, if you felt calm or unafraid during the experience, it can be interpreted as an auspicious sign — indicating that long-standing worries will dissolve and things you have been working toward will flow smoothly. If the elevator stopped mid-fall or you escaped unharmed, this is a strong indicator of overcoming adversity and gaining new opportunities, symbolizing resilience and eventual success.",
      "context": "꿈속에서 추락 도중 두려움보다 안도감을 느꼈거나, 추락 후 살아남거나 탈출에 성공한 경우"
    },
    {
      "type": "neutral",
      "korean": "엘리베이터가 추락하는 꿈은 현재 자신이 겪고 있는 불안한 심리 상태를 무의식이 그대로 반영한 것일 수 있어요. 현실에서 스트레스가 많거나 중요한 결정을 앞두고 있을 때 이런 꿈을 자주 꾸게 됩니다. 이 경우 꿈 자체가 예언적 의미를 가진다기보다는, 자신의 감정과 심리 상태를 돌아보게 해주는 신호로 받아들이는 것이 좋습니다. 엘리베이터는 삶의 방향과 여정을 상징하므로, 현재 어떤 방향으로 나아가고 있는지 점검해 볼 필요가 있다는 메시지로 해석할 수 있어요.",
      "english": "A falling elevator dream can often be a neutral psychological reflection of current anxieties, stress, or uncertainty rather than a prophetic warning. When facing major decisions or high-pressure situations, the subconscious frequently produces such imagery. In this interpretation, the dream serves as a signal to examine your emotional state and life direction rather than as a literal omen. The elevator symbolizes your life journey and personal trajectory — the dream invites you to pause and reflect on where you are headed.",
      "context": "현재 직장이나 인간관계, 또는 중요한 결정 앞에서 스트레스나 불안감을 느끼고 있는 상황"
    }
  ],
  "variations": [
    {
      "keyword_ko": "엘리베이터 추락 꿈",
